def load_data():
    x=[]; y=[]
    with open('/app/spectrum.csv', newline='') as f:
        reader=csv.reader(f)
        next(reader)
        for row in reader:
            if len(row)>=2:
                x.append(float(row[0]))
                y.append(float(row[1]))
    return x,y

def solve_linear(A,b):
    n=len(b)
    M=[A[i][:]+[b[i]] for i in range(n)]
    for col in range(n):
        piv=max(range(col,n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col])<1e-18:
            return None
        if piv!=col:
            M[col],M[piv]=M[piv],M[col]
        pv=M[col][col]
        for j in range(col,n+1):
            M[col][j]/=pv
        for r in range(n):
            if r!=col:
                fac=M[r][col]
                if abs(fac)>1e-18:
                    for j in range(col,n+1):
                        M[r][j]-=fac*M[col][j]
    return [M[i][n] for i in range(n)]

def fit_peak(x,y,lo,hi):
    xs=[]; ys=[]
    for xv,yv in zip(x,y):
        if lo<=xv<=hi:
            xs.append(xv); ys.append(yv)
    n=len(xs)
    imax=max(range(n), key=lambda i: ys[i])
    x0=xs[imax]
    c0=min(ys)
    A0=max(ys)-c0
    half=c0+0.5*A0
    li=imax
    while li>0 and ys[li]>half:
        li-=1
    ri=imax
    while ri<n-1 and ys[ri]>half:
        ri+=1
    if li>0 and ri<n-1:
        yl0,yl1=ys[li],ys[li+1]
        xl0,xl1=xs[li],xs[li+1]
        if abs(yl1-yl0)>1e-12:
            xl=xl0+(half-yl0)*(xl1-xl0)/(yl1-yl0)
        else:
            xl=xl0
        yr0,yr1=ys[ri-1],ys[ri]
        xr0,xr1=xs[ri-1],xs[ri]
        if abs(yr1-yr0)>1e-12:
            xr=xr0+(half-yr0)*(xr1-xr0)/(yr1-yr0)
        else:
            xr=xr0
        g0=max(1.0,0.5*(xr-xl))
    else:
        g0=10.0
    p=[x0,math.log(g0),math.log(max(A0,1e-9)),c0]
    lam=1e-3
    last_cost=None

def main():
    x,y=load_data()
    windows={'D':(1200.0,1450.0),'G':(1500.0,1700.0),'2D':(2500.0,2850.0)}
    out={}
    for name,(lo,hi) in windows.items():
        res,rms,its,n=fit_peak(x,y,lo,hi)
        out[name]=res
        print(name,res,'rmse',rms,'iter',its,'n',n)
    out['ID_IG']=out['D']['amplitude']/out['G']['amplitude']
    print('ID_IG',out['ID_IG'])
    with open('/app/results.json','w') as f:
        json.dump(out,f,indent=2)
    print('wrote /app/results.json')
